DROP TABLE IF EXISTS `treatment_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `treatment_details` (
  `Treatment_ID` int NOT NULL,
  `Visit_ID` int DEFAULT NULL,
  `Treatment_Type` varchar(100) DEFAULT NULL,
  `Treatment_Name` varchar(150) DEFAULT NULL,
  `Medication_Prescribed` varchar(255) DEFAULT NULL,
  `Dosage` varchar(100) DEFAULT NULL,
  `Instructions` text,
  `Treatment_Start_Date` date DEFAULT NULL,
  `Treatment_End_Date` date DEFAULT NULL,
  `Duration_Days` int DEFAULT NULL,
  `Status` varchar(50) DEFAULT NULL,
  `Outcome` varchar(100) DEFAULT NULL,
  `Direct_Treatment_Cost` decimal(12,2) DEFAULT NULL,
  `Total_Episode_Cost` decimal(12,2) DEFAULT NULL,
  `Treatment_Description` text,
  PRIMARY KEY (`Treatment_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

