DROP TABLE IF EXISTS `visit_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `visit_details` (
  `Visit_ID` int NOT NULL,
  `Patient_ID` int DEFAULT NULL,
  `Doctor_ID` int DEFAULT NULL,
  `Visit_Date` date DEFAULT NULL,
  `Visit_Year` int DEFAULT NULL,
  `Visit_Month` int DEFAULT NULL,
  `Visit_Month_Name` varchar(20) DEFAULT NULL,
  `Visit_Quarter` varchar(10) DEFAULT NULL,
  `Visit_Type` varchar(50) DEFAULT NULL,
  `Visit_Status` varchar(50) DEFAULT NULL,
  `Diagnosis` varchar(150) DEFAULT NULL,
  `Diagnosis_Code` varchar(50) DEFAULT NULL,
  `Reason_for_Visit` varchar(255) DEFAULT NULL,
  `Follow_Up_Required` varchar(10) DEFAULT NULL,
  `Prescribed_Medications` varchar(255) DEFAULT NULL,
  `Visit_Duration_Mins` int DEFAULT NULL,
  PRIMARY KEY (`Visit_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

